// Offline registry of common travel providers (airlines, car rental, stays, rail, tours), recognised
// from a link, a typed name or a flight number. Logos are simple-icons glyphs (see providerLogos.ts,
// generated by scripts/build-provider-logos.mjs); providers without one get a monogram tile.

import { LOGOS } from "./providerLogos";

export type ProviderKind =
  | "airline"
  | "car_rental"
  | "hotel"
  | "platform"
  | "rail"
  | "bus"
  | "activity"
  | "ride";

export interface Provider {
  id: string;
  name: string;
  kind: ProviderKind;
  /** Website opened from the logo. */
  url: string;
  /** Host names; `name.*` matches any top-level domain. */
  domains: string[];
  /** Brand colour; taken from the logo when omitted. */
  color?: string;
  /** simple-icons slug. */
  logo?: string;
  /** Up to three characters for the monogram tile. */
  mono?: string;
  iata?: string[];
  aliases?: string[];
}

const A = "airline";
const C = "car_rental";
const H = "hotel";
const P = "platform";

/** Registry row: domains and IATA codes space-separated; the website defaults to www.<first domain>. */
function p(
  id: string,
  name: string,
  kind: ProviderKind,
  domains: string,
  extra: Omit<Partial<Provider>, "iata"> & { iata?: string } = {},
): Provider {
  const ds = domains.split(" ");
  const iata = extra.iata?.split(" ");
  const url = extra.url ?? `https://www.${domains.split(" ", 1).join("").replace(/\.\*$/, ".com")}`;
  return { ...extra, id, name, kind, url, domains: ds, iata };
}

