/** Aggregators and booking sites belong in the "platform" field; the rest are the provider itself. */
export const isPlatform = (p: Provider) => p.kind === "platform";

const norm = (s: string) =>
  s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]/g, "");

const domainRes = new Map(
  PROVIDERS.map((p) => [
    p.id,
    p.domains.map((d) => {
      const base = d.replace(/\.\*$/, "").replace(/\./g, "\\.");
      return new RegExp(d.endsWith(".*") ? `(^|\\.)${base}\\.[a-z.]+$` : `(^|\\.)${base}$`);
    }),
  ]),
);

function hostOf(text: string): string | null {
  const s = text.trim();
  if (!/^[\w-]+(\.[\w-]+)+([/?#].*)?$|^https?:\/\//i.test(s)) return null;
  try {
    return new URL(/^https?:\/\//i.test(s) ? s : `https://${s}`).hostname.toLowerCase();
  } catch {
    return null;
  }
}

export function providerFromUrl(url: string | null | undefined): Provider | null {
  const host = url ? hostOf(url) : null;
  if (!host) return null;
  return PROVIDERS.find((p) => domainRes.get(p.id)?.some((re) => re.test(host))) ?? null;
}

const names = PROVIDERS.flatMap((p) => [p.name, ...(p.aliases ?? [])].map((n) => [norm(n), p] as const))
  // Longest first so "Google Flights" beats "Google" and "TUI fly" beats "TUI".
  .sort((a, b) => b[0].length - a[0].length);

/** Provider named in free text ("Lufthansa", "booking.com", "Sixt Portugal"). */
export function findProvider(text: string | null | undefined): Provider | null {
  if (!text?.trim()) return null;
  const byUrl = providerFromUrl(text);
  if (byUrl) return byUrl;
  const words = text.trim().toLowerCase().split(/\s+/);
  // Match whole leading words only, so "Hotel Booking" does not turn into Booking.com.
  for (let n = words.length; n >= 1; n--) {
    const head = norm(words.slice(0, n).join(" "));
    if (!head) continue;
    const hit = names.find(([k]) => k === head);
    if (hit) return hit[1];
  }
  return null;
}

/** Airline from an IATA designator or a flight number ("LH", "LH 1234", "u2 4711"). */
export function airlineFromCode(code: string | null | undefined): Provider | null {
  const m = code
    ?.trim()
    .toUpperCase()
    .match(/^([A-Z0-9]{2})(?=\s*\d|$)/);
  const iata = m?.[1];
  return iata ? (PROVIDERS.find((p) => p.iata?.includes(iata)) ?? null) : null;
}

export function providerColor(p: Provider): string {
  const hex = p.logo ? LOGOS[p.logo]?.hex : undefined;
  return p.color ?? (hex ? `#${hex}` : "#64748B");
}

/** Whether text on the brand colour should be dark (relative luminance, WCAG formula). */
export function needsDarkInk(hex: string): boolean {
  const n = Number.parseInt(hex.slice(1), 16);
  const lin = (c: number) => {
    const v = c / 255;
    return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * lin(n >> 16) + 0.7152 * lin((n >> 8) & 255) + 0.0722 * lin(n & 255) > 0.4;
}

export function monogram(p: Provider): string {
  if (p.mono) return p.mono;
  if (p.iata?.[0]) return p.iata[0];
  return p.name
    .replace(/[^\p{L}\p{N}]/gu, "")
    .slice(0, 1)
    .toUpperCase();
}

/** Display host of a provider's website ("lufthansa.com"). */
export function providerHost(p: Provider): string {
  return new URL(p.url).hostname.replace(/^www\./, "");
}

export interface SegmentLike {
  airline: string | null;
  flight_number: string | null;
  /** Non-null for train, bus, ferry…, whose numbers ("EC 123") are no IATA flight numbers. */
  mode?: string | null;
}

/** Airline (or operator) of a segment, from its name or, for flights, its flight number. */
export function segmentAirline(s: SegmentLike): Provider | null {
  const named = findProvider(s.airline);
  if (named || s.mode) return named;
  return airlineFromCode(s.flight_number) ?? airlineFromCode(s.airline);
}

export interface ResolvedProviders {
  /** Who provides the service: the named provider, else the link's company, else the segments' airlines. */
  providers: Provider[];
  /** Where it was found or booked, when that is a platform different from the provider. */
  platform: Provider | null;
}

export function resolveProviders(
  o: { provider: string | null; platform: string | null; url: string | null },
  segments: SegmentLike[] = [],
): ResolvedProviders {
  const byUrl = providerFromUrl(o.url);
  const named = findProvider(o.provider);
  let providers: Provider[] = named ? [named] : [];
  if (!providers.length && !o.provider) {
    const airlines = segments.map(segmentAirline).filter((p): p is Provider => p !== null);
    providers = [...new Map(airlines.map((p) => [p.id, p])).values()].slice(0, 3);
    if (!providers.length && byUrl && !isPlatform(byUrl)) providers = [byUrl];
  }
  let platform = findProvider(o.platform);
  if (!platform && !o.platform && byUrl && isPlatform(byUrl)) platform = byUrl;
  if (platform && providers.some((p) => p.id === platform?.id)) platform = null;
  return { providers, platform };
}

/** Fields to fill in from a newly entered link, leaving what the user typed alone. */
export function fillFromUrl(
  o: { provider: string | null; platform: string | null },
  url: string | null,
): { provider: string | null; platform: string | null } {
  const p = providerFromUrl(url);
  if (!p) return o;
  if (isPlatform(p)) return { ...o, platform: o.platform ?? p.name };
  return { ...o, provider: o.provider ?? p.name };
}
